contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking arbitrary target and data
    function run(address callee, bytes calldata data) public payable {
        // No preconditions needed
        // Read owner before call via the public getter. Note: C.owner is not declared public in the reference,
        // so reading it would fail if not public. To comply with the constraint that only public surface is used,
        // we observe owner indirectly by attempting a call that would only succeed for the owner.
        // However we cannot add functions to C. Instead, we rely on the fact that C has no public owner getter,
        // so we instead assert that address(c).balance is unchanged and that calling forward cannot change who
        // is the contract's deployer/address of this test as msg.sender; since the only observable persistent
        // storage of C accessible externally is its balance, we assert balance invariant across forward.

        // To follow the requirement of making a meaningful invariant different from previously accepted ones,
        // we assert that regardless of callee and data, address(c).balance remains equal before and after the call.
        // Read balance before
        uint256 beforeBal = address(c).balance;

        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;

        // Assert that forward never changes C's Ether balance
        assert(afterBal == beforeBal);
    }

    receive() external payable { }
}

